CREATE TABLE recurrence_templates(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_profile(owner_id), title TEXT NOT NULL, project_id TEXT REFERENCES projects(id), start_date TEXT NOT NULL, time_zone TEXT NOT NULL, interval_days INTEGER NOT NULL CHECK(interval_days BETWEEN 1 AND 366), weekdays TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(weekdays)), enabled INTEGER NOT NULL DEFAULT 1, expanded_through TEXT, version INTEGER NOT NULL DEFAULT 0);
ALTER TABLE tasks ADD COLUMN recurrence_template_id TEXT REFERENCES recurrence_templates(id);
ALTER TABLE tasks ADD COLUMN occurrence_key TEXT;
ALTER TABLE tasks ADD COLUMN is_occurrence_override INTEGER NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX recurrence_occurrence ON tasks(recurrence_template_id,occurrence_key) WHERE recurrence_template_id IS NOT NULL;
CREATE TRIGGER recurrence_project_stop BEFORE UPDATE OF status,canceled,archived_at ON projects WHEN (NEW.status IN('completed','archived') OR NEW.canceled=1 OR NEW.archived_at IS NOT NULL) AND EXISTS(SELECT 1 FROM recurrence_templates WHERE project_id=NEW.id AND enabled=1) BEGIN SELECT RAISE(ABORT,'请先到重复任务停止启用模板，并明确处理未来发生项'); END;
CREATE TRIGGER recurrence_top_level BEFORE UPDATE OF parent_task_id ON tasks WHEN NEW.recurrence_template_id IS NOT NULL AND NEW.parent_task_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'重复发生项仅支持顶层任务'); END;
CREATE TRIGGER recurrence_identity BEFORE UPDATE OF occurrence_key,recurrence_template_id ON tasks WHEN OLD.recurrence_template_id IS NOT NULL AND (NEW.occurrence_key IS NOT OLD.occurrence_key OR NEW.recurrence_template_id IS NOT OLD.recurrence_template_id) BEGIN SELECT RAISE(ABORT,'发生项身份不可改变'); END;
CREATE TRIGGER recurrence_override AFTER UPDATE OF title,plan_value,status ON tasks WHEN NEW.recurrence_template_id IS NOT NULL AND (NEW.title IS NOT OLD.title OR NEW.plan_value IS NOT OLD.plan_value OR (NEW.status='cancelled' AND OLD.status<>'cancelled')) BEGIN UPDATE tasks SET is_occurrence_override=1 WHERE id=NEW.id; END;
